import random

def play_game():
    """
    Plays a game of Rock, Paper, Scissors against the computer.
    """
    print("Welcome to Rock, Paper, Scissors!")

    # Define the possible moves
    moves = ["rock", "paper", "scissors"]

    # Computer chooses a move randomly
    computer_move = random.choice(moves)

    # Player chooses a move
    player_move = input("Enter your move (rock, paper, scissors): ").lower()

    # Determine the winner
    if player_move == "rock":
        if computer_move == "paper":
            print("You lose! Paper beats rock.")
        elif computer_move == "scissors":
            print("You win! Rock beats scissors.")
        else:
            print("Invalid move. Try again!")
    elif player_move == "paper":
        if computer_move == "rock":
            print("You win! Paper beats rock.")
        elif computer_move == "scissors":
            print("You lose! Scissors beats paper.")
        else:
            print("Invalid move. Try again!")
    elif player_move == "scissors":
        if computer_move == "rock":
            print("You lose! Rock beats scissors.")
        elif computer_move == "paper":
            print("You win! Scissors beats paper.")
        else:
            print("Invalid move. Try again!")
    else:
        print("Invalid move. Try again!")

    # Play another game?
    play_again = input("Do you want to play again? (yes/no): ").lower()
    if play_again == "yes":
        play_game()
    else:
        print("Thanks for playing!")

# Call the function to start the game
play_game()
```

This program defines a function `play_game()` that prompts the player to enter their move, chooses a random move for the computer, and determines the winner based on the rules of Rock, Paper, Scissors. The function then asks the player if they want to play again.
